{
  "name": "@iiiokojiadbi/shift",
  "version": "0.40.0",
  "description": "The agent decides by itself when to shift: it keeps a work board and task folders, writes a letter to itself, and continues from where it stopped.",
  "license": "MIT",
  "type": "module",
  "homepage": "https://github.com/iiiokojiadbi/shift#readme",
  "bugs": {
    "url": "https://github.com/iiiokojiadbi/shift/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/iiiokojiadbi/shift.git",
    "directory": "adapters/npm"
  },
  "keywords": [
    "pi-package",
    "opencode-plugin",
    "pi",
    "opencode",
    "agent",
    "context",
    "memory",
    "handoff"
  ],
  "files": [
    "index.ts",
    "server.ts",
    "store.ts",
    "core",
    "README.md",
    "LICENSE"
  ],
  "exports": {
    "./server": "./server.ts",
    "./package.json": "./package.json"
  },
  "pi": {
    "extensions": [
      "./index.ts"
    ]
  },
  "peerDependencies": {
    "@earendil-works/pi-coding-agent": "*",
    "typebox": "*"
  },
  "peerDependenciesMeta": {
    "@earendil-works/pi-coding-agent": {
      "optional": true
    },
    "typebox": {
      "optional": true
    }
  }
}

import { resolve } from 'node:path'
import type {
  CompactionEntry,
  CompactionResult,
  ExtensionAPI,
  ExtensionContext,
  InputEvent,
  SessionEntry,
} from '@earendil-works/pi-coding-agent'
import { estimateTokens, findCutPoint, SettingsManager } from '@earendil-works/pi-coding-agent'
import type { TSchema } from 'typebox'
import type { Courier, Gauge, GaugeKeeper, LetGoHarness, Looks, Loop, LoopState, Note, Project, SessionFile, WaitNote } from './core/index'
import {
  addGrowth,
  afterTool,
  afterTurn,
  afterWrite,
  atPrompt,
  beforeTool,
  checkpointChanged,
  contentChars,
  countGrowth,
  dropWaiting,
  FRESH_GAUGE,
  FRESH_LOOKS,
  FRESH_LOOP,
  formatK,
  gaugeStatus,
  HELD,
  holdOwner,
  initialMap,
  letGoGauge,
  MOD,
  mapCheckpoint,
  RESUME_COMMAND,
  RESUME_DESCRIPTION,
  renderSessionFiles,
  resumeShift,
  SETTINGS,
  SHIFT_COMMAND,
  SHIFT_NOW_DESCRIPTION,
  SOURCES,
  sessionDoctrine,
  sessionFiles,
  shiftBase,
  shiftNow,
  startSession,
  TASKS_COMMAND,
  TASKS_DESCRIPTION,
  TOOLS,
  tasksView,
} from './core/index'
import { projectAt } from './store'

const OURS: ReadonlySet<string> = new Set(TOOLS.map(tool => tool.name))
// pi's tools that only read: nothing to look at after them.
const READING: ReadonlySet<string> = new Set(['read', 'grep', 'find', 'ls'])

// The custom entry that keeps a wait note across a reload: the extension's own state lives only as long as its runtime.
const WAIT_ENTRY = `${MOD}:wait`

export default function shift(pi: ExtensionAPI): void {
  let loop: LoopState = FRESH_LOOP
  let gauge: Gauge = FRESH_GAUGE
  // Set by the owner's own input, consumed by the run it starts.
  let ownerTyped = false
  // false when the project's settings turn the mod off; read at each session start.
  let enabled = true
  // The documents' tocs and the map are refreshed at the first run of a session, before anything looks at them.
  let mapFile: SessionFile | null | undefined
  let loadedBlock: string | null = null
  const mapEntry = `${MOD}:map`
  const fileEntry = `${MOD}:map-file`

  function restoreBranch(ctx: ExtensionContext) {
    looks = FRESH_LOOKS
    mapFile = undefined
    loadedBlock = null
    outside.clear()
    for (const entry of ctx.sessionManager.getBranch().toReversed()) {
      if (entry.type === 'compaction') break
      if (entry.type !== 'custom') continue
      if (entry.customType === mapEntry && !looks.map) looks = { ...looks, ...(entry.data as ReturnType<typeof mapCheckpoint>) }
      if (entry.customType === fileEntry) {
        mapFile = entry.data as SessionFile | null
        break
      }
    }
    if (!looks.map) mapFile = undefined
  }
  // The records as last seen and the agent's tools running now; what changed before each tool began, by its call.
  let looks: Looks = FRESH_LOOKS
  const outside = new Map<string, Note[]>()

  const text = (body: string) => ({ content: [{ type: 'text' as const, text: body }], details: undefined })
  const schema = (shape: object) => shape as TSchema

  // Every tool of the table; the session's start takes the ones the project does not show out of the active set.
  for (const tool of TOOLS) {
    pi.registerTool({
      name: tool.name,
      label: tool.label,
      description: tool.description,
      parameters: schema(tool.schema),
      ...(tool.writes ? { executionMode: 'sequential' as const } : {}),
      async execute(_id, params, _signal, _onUpdate, ctx) {
        const done = await tool.run(params as Record<string, unknown>, {
          project: () => projectAt(ctx.cwd),
          sessionId: async () => ctx.sessionManager.getSessionId(),
          now: async () => Date.now(),
          subagent: false,
          loop: loopOf(ctx),
          loaded: async () => loadedBlock,
          status: () => gaugeStatus(keeperOf(ctx, () => projectAt(ctx.cwd))),
          cannotLetGo: async () => cannotLetGo(ctx),
        })
        if ('deny' in done) throw new Error(done.deny)

        return text(done.result)
      },
    })
  }

  pi.registerCommand(TASKS_COMMAND, {
    description: TASKS_DESCRIPTION,
    handler: async (_args, ctx) => ctx.ui.notify(await tasksView(await projectAt(ctx.cwd)), 'info'),
  })

  pi.registerCommand(SHIFT_COMMAND, {
    description: SHIFT_NOW_DESCRIPTION,
    handler: async (args, ctx) => {
      if (!enabled) return ctx.ui.notify(`${MOD} is off in this project: ${SETTINGS} has enabled = false.`, 'info')
      // Typed mid-run, it waits for the run to end, as Claude Code holds a command until the turn is over.
      // The letter's clearing goes on the branch before the message that carries it, as `branchNote` reads them.
      const now = await shiftNow(loopOf(ctx), args.trim())
      await now.delivered()
      pi.sendUserMessage(now.text, ctx.isIdle() ? undefined : { deliverAs: 'followUp' })
    },
  })

  pi.registerCommand(RESUME_COMMAND, {
    description: RESUME_DESCRIPTION,
    // The owner's words typed with the command go after the letter, as their own message that starts the turn.
    handler: async (args, ctx) => {
      if (!enabled) return ctx.ui.notify(`${MOD} is off in this project: ${SETTINGS} has enabled = false.`, 'info')
      const resumed = await resumeShift(await projectAt(ctx.cwd))
      ctx.ui.notify(resumed.text, 'info')
      if (resumed.prompt === undefined) return
      // The newest letter goes now: one waiting for the owner's message is not told again. Its clearing goes on the
      // branch before the message, as `branchNote` reads them.
      await dropWaiting(loopOf(ctx))
      const words = args.trim()
      // Typed mid-run, both wait for the run to end.
      const busy = ctx.isIdle() ? {} : { deliverAs: 'followUp' as const }
      pi.sendMessage({ customType: MOD, content: resumed.prompt, display: true }, { triggerTurn: words === '', ...busy })
      if (words !== '') pi.sendUserMessage(words, ctx.isIdle() ? undefined : { deliverAs: 'followUp' })
    },
  })

  // Tools are registered before the project is known, so an off project only takes them out of the active set.
  // A wait note survives a reload: the last wait entry on the branch says whether one is still undelivered.
  pi.on('session_start', async (_event, ctx) => {
    const start = await startSession(await projectAt(ctx.cwd))
    enabled = start.enabled
    restoreBranch(ctx)
    for (const row of start.rows) tell(ctx, row.text, row.level)
    const shown = start.tools.map(tool => tool.name)
    pi.setActiveTools([...pi.getActiveTools().filter(name => !OURS.has(name)), ...shown])
    if (!enabled) return
    loop = { ...loop, note: branchNote(ctx) }
  })

  // Another branch has its own wait note, or none: a letter of the branch left behind never goes with this one.
  // Its history too: the gauge is counted anew from the branch.
  pi.on('session_tree', async (_event, ctx) => {
    if (!enabled) return
    loop = { ...loop, note: branchNote(ctx) }
    gauge = FRESH_GAUGE
    restoreBranch(ctx)
  })

  // The owner's own input: only a message that starts a run takes the waiting letter with it. An extension's message
  // comes after any owner input another extension took without a run, so it clears what that left.
  pi.on('input', async (event, ctx) => {
    if (!enabled) return
    if (event.source === 'extension') {
      ownerTyped = false
      return
    }
    // While a shift waits for its run to end or lets the history go, the owner's message is held and goes after the
    // letter: pi sends what was typed during the let-go as soon as it ends, before the letter. A command runs as it is.
    if (!event.text.startsWith('/') && (await holdOwner(loopOf(ctx), { text: event.text, attachments: event.images }))) {
      tell(ctx, HELD, 'info')
      return { action: 'handled' as const }
    }
    if (event.streamingBehavior === undefined) ownerTyped = true
  })

  // The doctrine every run; between turns a hint, and after a wait the letter, follow the owner's message.
  pi.on('before_agent_start', async (event, ctx) => {
    if (!enabled) return
    const project = once(ctx)
    const loadedProject = await project()
    // The doctrine at the settings' places: a shift may have moved a record.
    event.systemPromptOptions.sections[MOD] = sessionDoctrine(loadedProject.settings).doctrineBody
    // A session's first run refreshes the tocs and the map before the documents' stamps are first looked at.
    if (mapFile === undefined) {
      const files = await sessionFiles(loadedProject)
      mapFile = files.find(file => file.path === loadedProject.settings.files.shift) ?? null
      looks = { ...looks, map: await initialMap(loadedProject, files), mapNotes: [] }
      pi.appendEntry(fileEntry, mapFile)
      pi.appendEntry(mapEntry, mapCheckpoint(looks))
    }
    if (mapFile) event.systemPromptOptions.sections.shift_map = renderSessionFiles([mapFile]) ?? ''
    // Records changed between runs — by the owner's hand or another session — a hint, and after a wait the letter.
    const owner = event.messageType === 'user' && ownerTyped
    if (owner) ownerTyped = false
    const told = await atPrompt(courierOf(ctx, project), { runStarts: true, owner })
    if (told.notes.length > 0) await told.delivered()
    // The other records go where pi puts AGENTS.md. Keep the map in its own stable section. Read after the notes: a toc a script left stale is written with its note, never silently before it.
    const loaded = await sessionFiles(loadedProject, { refresh: false })
    const others = loaded.filter(file => file.path !== loadedProject.settings.files.shift)
    loadedBlock = renderSessionFiles(mapFile ? [mapFile, ...others] : others)
    const ours = new Set(loaded.map(file => file.path))
    event.systemPromptOptions.contextFiles = [
      ...event.systemPromptOptions.contextFiles.filter(file => !ours.has(file.path)),
      ...others.map(file => ({ path: file.path, content: file.text })),
    ]
    if (told.notes.length === 0) return

    return { message: { customType: MOD, content: told.notes.join('\n\n'), display: true } }
  })

  // Every message of the history is counted by source.
  pi.on('message_end', async (event, ctx) => {
    if (!enabled) return
    const source = growthSource(event.message)
    if (source !== null)
      await countGrowth(
        keeperOf(ctx, () => projectAt(ctx.cwd)),
        source,
        messageChars(event.message),
      )
  })

  // Every note to the agent mid-run goes with a tool's result: what changed in the records around a tool of the agent,
  // the docs after a write, a hint. A nested tool's write gets only the docs.
  pi.on('tool_call', async (event, ctx) => {
    if (!enabled || event.parentToolCallId !== undefined) return
    outside.set(event.toolCallId, await beforeTool(courierOf(ctx, once(ctx))))
  })

  pi.on('tool_result', async (event, ctx) => {
    if (!enabled) return
    const path = (event.toolName === 'edit' || event.toolName === 'write') && !event.isError ? event.input.path : undefined
    const written = typeof path === 'string' ? resolve(ctx.cwd, path) : undefined
    const courier = courierOf(ctx, once(ctx))
    if (event.parentToolCallId !== undefined) {
      if (written !== undefined) await afterWrite(courier, written)
      return
    }
    const matched = outside.has(event.toolCallId)
    const before = outside.get(event.toolCallId) ?? []
    outside.delete(event.toolCallId)
    const added = await afterTool(courier, before, {
      own: OURS.has(event.toolName),
      readOnly: READING.has(event.toolName),
      written,
      content: typeof event.input.content === 'string' ? event.input.content : undefined,
      shellWrite: matched && event.toolName === 'bash' && !event.isError,
    })
    if (added.length === 0) return

    return {
      content: [...event.content, ...added.map(each => ({ type: 'text' as const, text: each }))],
      structuredContent: event.structuredContent,
    }
  })

  // A call blocked before it ran has no result: it ends here, so the tools after it still know what runs.
  pi.on('tool_execution_end', async (event, ctx) => {
    if (!enabled || !outside.has(event.toolCallId)) return
    outside.delete(event.toolCallId)
    await afterTool(courierOf(ctx), [], null)
  })

  // pi's own let-go at its threshold would go without the letter's Hold: an accepted shift lets go once the run settles.
  pi.on('session_before_compact', async event => {
    if (enabled && loop.pending !== null && event.reason === 'threshold') return { cancel: true }
  })

  // The shift lets go once the run has settled: compacting aborts whatever runs, so never from inside the turn. Not
  // awaited: pi defers every prompt until its settled handlers return, so an owner's message sent during the let-go
  // would come only after the shift is over, too late to be held, and run before the shift's message.
  pi.on('agent_settled', async (event, ctx) => {
    if (loop.pending === null) return
    void projectAt(ctx.cwd)
      .then(project => afterTurn(project, loopOf(ctx), letGoOf(ctx), event.aborted))
      .catch((error: unknown) => tell(ctx, `the shift did not finish: ${String(error)}`, 'error'))
  })

  // Any compaction starts a new stretch; one the agent did not ask for is told to it at its next look.
  pi.on('session_compact', event => {
    gauge = letGoGauge(event.reason !== 'manual')
    mapFile = undefined
    looks = { ...looks, map: undefined, mapNotes: [] }
  })

  // The notes to the agent over the extension's runtime: the looks at the records, the loop and the gauge.
  function courierOf(ctx: ExtensionContext, project: () => Promise<Project> = once(ctx)): Courier {
    return {
      loop: loopOf(ctx),
      gauge: keeperOf(ctx, project),
      project,
      looks: async () => looks,
      updateLooks: async change => {
        const previous = looks
        looks = change(previous)
        if (looks.map && checkpointChanged(previous, looks)) pi.appendEntry(mapEntry, mapCheckpoint(looks))
      },
    }
  }

  // The loop's state in the extension's runtime; a wait note also in a session entry, so it survives a reload.
  function loopOf(ctx: ExtensionContext): Loop {
    return {
      read: async () => loop,
      update: async change => {
        const before = loop
        loop = change(loop)
        if (loop.note !== before.note) pi.appendEntry(WAIT_ENTRY, { note: loop.note })
      },
      tell: (row, level) => tell(ctx, row, level),
    }
  }

  // pi compacts with callbacks; the next turn starts from a custom message.
  function letGoOf(ctx: ExtensionContext): LetGoHarness {
    return {
      fill: async () => ctx.getContextUsage()?.tokens ?? undefined,
      letGo: instructions =>
        new Promise<Awaited<ReturnType<LetGoHarness['letGo']>>>(done => {
          ctx.compact({
            customInstructions: instructions,
            onError: error => done({ skip: error.message }),
            onComplete: (result: CompactionResult) =>
              done({
                messages: [{ role: 'digest', text: result.summary }],
                before: result.tokensBefore ?? undefined,
                after: result.estimatedTokensAfter ?? undefined,
              }),
          })
        }).catch((error: unknown) => ({ skip: `did not start: ${String(error)}` })),
      continueWith: async (prompt, attachments) => {
        // The images of the owner's held messages go with it as pi gave them.
        const images = (attachments ?? []) as NonNullable<InputEvent['images']>
        const content = images.length === 0 ? prompt : [{ type: 'text' as const, text: prompt }, ...images]
        pi.sendMessage({ customType: MOD, content, display: true }, { triggerTurn: true })
      },
    }
  }

  // The gauge in the extension's runtime; the history and the base read from the session. pi compacts by itself once
  // the free room falls under `reserveTokens`.
  function keeperOf(ctx: ExtensionContext, project: () => Promise<Project>): GaugeKeeper {
    return {
      read: async () => gauge,
      update: async change => {
        gauge = change(gauge)
      },
      history: async () => {
        let counted = FRESH_GAUGE
        for (const message of ctx.sessionManager.buildSessionProjection().messages) {
          const source = growthSource(message)
          if (source !== null) counted = addGrowth(counted, source, messageChars(message))
        }

        return counted.growth
      },
      base: async () => shiftBase(await project(), ctx.sessionManager.getSessionId()),
      reading: async () => {
        const usage = ctx.getContextUsage()
        const window = usage?.contextWindow ?? ctx.model?.contextWindow ?? 0
        const settings = SettingsManager.create(ctx.cwd).getCompactionSettings(ctx.model)

        return { tokens: usage?.tokens ?? undefined, window, threshold: settings.enabled ? window - settings.reserveTokens : undefined }
      },
    }
  }
}

// The wait note of the branch the session stands on: its last wait entry, written whenever the note changes. A note
// cleared by a message rewound off this branch still waits on it: every clearing is followed by the message that
// carries the letter — the mod's, or the owner's /shift. The system prompt pi records as a message carries none.
function branchNote(ctx: ExtensionContext): WaitNote | null {
  let followed = false
  for (const entry of ctx.sessionManager.getBranch().toReversed()) {
    if ((entry.type === 'custom_message' && entry.customType === MOD) || (entry.type === 'message' && entry.message.role !== 'system'))
      followed = true
    if (entry.type !== 'custom' || entry.customType !== WAIT_ENTRY) continue
    const note = (entry.data as { note: WaitNote | null } | undefined)?.note ?? null
    if (note !== null || followed) return note
  }

  return null
}

// What a let-go summarizes: the conversation, not the system prompt pi records as a message of its own.
function summarized(entry: SessionEntry): boolean {
  return entry.type === 'message' ? entry.message.role !== 'system' : entry.type === 'custom_message' || entry.type === 'branch_summary'
}

// pi lets go only of the messages before the cut it finds by keepRecentTokens, counted from the last let-go; with none
// there — a history no bigger, the cut on its first message — it refuses as "session too small". The same cut is
// found here, before the shift is accepted.
function cannotLetGo(ctx: ExtensionContext): string | null {
  const keep = SettingsManager.create(ctx.cwd).getCompactionSettings(ctx.model).keepRecentTokens
  const branch = ctx.sessionManager.getBranch()
  const last = branch.findLastIndex(entry => entry.type === 'compaction')
  const kept = last === -1 ? -1 : branch.findIndex(entry => entry.id === (branch[last] as CompactionEntry).firstKeptEntryId)
  const start = kept === -1 ? Math.max(0, last + 1) : kept
  const cut = findCutPoint(branch, start, branch.length, keep)
  if (branch.slice(start, cut.firstKeptEntryIndex).some(summarized)) return null
  const since = branch.slice(start).reduce((sum, entry) => sum + (entry.type === 'message' ? estimateTokens(entry.message) : 0), 0)

  return `the history since the last let-go is about ${formatK(since)} tokens, and pi keeps its last ${formatK(keep)} whole, so it has nothing to let go.`
}

// The project loaded once for the hook at hand.
function once(ctx: ExtensionContext): () => Promise<Project> {
  const loading = projectAt(ctx.cwd)
  return () => loading
}

// A row for the owner; a context gone stale with its session has no one to tell.
function tell(ctx: ExtensionContext, row: string, kind: 'info' | 'warning' | 'error'): void {
  try {
    ctx.ui.notify(row, kind)
  } catch {
    // The row is in about.md all the same.
  }
}

// Who a message came from, as the hint names it; digests of earlier history and a shell output the owner kept out of
// the context are not counted.
function growthSource(message: { role: string; toolName?: string; excludeFromContext?: boolean }): string | null {
  if (message.excludeFromContext === true) return null
  if (message.role === 'assistant') return SOURCES.responses
  if (message.role === 'user' || message.role === 'bashExecution') return SOURCES.owner
  if (message.role === 'toolResult') return message.toolName ?? SOURCES.tools
  if (message.role === 'compactionSummary' || message.role === 'branchSummary') return null

  return SOURCES.attachments
}

// A shell command the owner ran has its command and output instead of content; a change of the system prompt carries
// its text in sections.
function messageChars(message: object): number {
  const sections =
    'sections' in message && typeof message.sections === 'object' && message.sections !== null
      ? Object.values(message.sections).reduce((sum: number, text) => sum + (typeof text === 'string' ? text.length : 0), 0)
      : 0
  if ('content' in message) return contentChars(message.content) + sections
  if ('output' in message && typeof message.output === 'string') return message.output.length

  return sections
}

import { resolve } from 'node:path'
import type { Plugin } from '@opencode/plugin'
import type {
  Courier,
  Gauge,
  GaugeKeeper,
  LetGoHarness,
  Level,
  Looks,
  Loop,
  LoopState,
  Note,
  PendingShift,
  Project,
  WaitNote,
} from './core/index'
import {
  addGrowth,
  afterTool,
  afterTurn,
  afterWrite,
  atPrompt,
  awaitShift,
  beforeTool,
  checkpointChanged,
  compactInstructions,
  contentChars,
  countGrowth,
  dropWaiting,
  FRESH_GAUGE,
  FRESH_LOOKS,
  FRESH_LOOP,
  gaugeStatus,
  HELD_NOTE,
  initialMap,
  letGoGauge,
  MOD,
  mapCheckpoint,
  RESUME_COMMAND,
  RESUME_DESCRIPTION,
  refreshDocs,
  renderSessionFiles,
  resumeShift,
  runEnded,
  SHIFT_COMMAND,
  SHIFT_NOW_DESCRIPTION,
  SOURCES,
  sessionDoctrine,
  sessionFiles,
  shiftBase,
  shiftNow,
  staleLayout,
  startSession,
  TASKS_COMMAND,
  TASKS_DESCRIPTION,
  TOOL,
  TOOLS,
  tasksView,
  unassistedInstructions,
} from './core/index'
import { projectAt } from './store'

type Definition = Plugin.Plugin

const OURS: ReadonlySet<string> = new Set(TOOLS.map(tool => tool.name))
// opencode's tools that only read, and those that write one file by `path`.
const READING: ReadonlySet<string> = new Set(['read', 'glob', 'grep'])
const WRITING: ReadonlySet<string> = new Set(['edit', 'write'])
// opencode keeps this much of the latest history whole beside the digest, unless its config says otherwise.
const KEPT_TOKENS = 15_000
// A token is about four characters: the step's tokens stand for the response's text, which the event does not carry.
const CHARS_PER_TOKEN = 4
// The rows the owner sees above what the mod sends the agent.
const CONTINUED = `${MOD}: the letter and the records`
// How long the owner's message waits for a shift's let-go before it goes as it is.
const HOLD_LIMIT = 10 * 60_000

// What the plugin keeps of one session; the plugin is one per project, shared by its sessions.
type Session = {
  // The project's settings turn the mod on for it, read as the session first comes; the rows that start it, told once.
  enabled: boolean
  rows: { text: string; level: Level }[]
  loop: LoopState
  // The loop's last update, which the next one waits for.
  updating: Promise<void>
  // The owner's last message through the prompt hook, which the next one waits for: messages held for a shift take its
  // message once and keep their order.
  prompting: Promise<void>
  gauge: Gauge
  looks: Looks
  // The last step's prompt size: the history as the model read it.
  fill: number | undefined
  // A run is going on; set when it starts, cleared at idle.
  busy: boolean
  // The Hold of the shift being let go, and what its let-go ended in.
  hold: string | undefined
  letGo: ((end: { text: string } | { error: string }) => void) | undefined
  // The inbox item of the let-go the mod asked for: its cancel ends the wait for it.
  letGoID: string | undefined
  // Runs started in the session: a tool that ends after its run did knows its turn is over.
  runs: number
  // The doctrine and the session's files as the session started or last let go: a block read anew every
  // request would show records the history has not reached yet and break the prompt's cache on every write.
  block: { doctrine: string; files: string | null } | undefined
}

type Ended = { sessionID: string; text?: string; error?: unknown; tokens?: { input?: number } }

const plugin: Definition = {
  id: MOD,
  async setup(ctx) {
    const root = ctx.location.directory
    const start = await startSession(await projectAt(root))
    if (!start.enabled) return
    // The docs' tocs and map are refreshed once, as the plugin starts: later the notes settle what changed, each with
    // its note.
    await sessionFiles(await projectAt(root)).catch(() => [])
    // The rows of the plugin's start — `.shift/` just kept out of git — go to the first session that comes.
    const startRows = [...start.rows]

    const sessions = new Map<string, Session>()
    const parents = new Map<string, string | null>()
    const windows = new Map<string, { window: number; threshold: number | undefined }>()
    const outside = new Map<string, Note[]>()
    let stopped = false

    // A session's state, its waiting letter read back from the plugin's storage the first time: it outlives a restart.
    async function state(sessionID: string, project: () => Promise<Project> = once()): Promise<Session> {
      const known = sessions.get(sessionID)
      if (known !== undefined) return known
      const note = ((await ctx.storage.get(waitKey(sessionID))) ?? null) as WaitNote | null
      // A shift accepted before the plugin reloaded lets go at the next run's end.
      const pending = ((await ctx.storage.get(pendingKey(sessionID))) ?? null) as PendingShift | null
      const saved = (await ctx.storage.get(`context:${sessionID}`)) as
        | { block: Session['block']; checkpoint: ReturnType<typeof mapCheckpoint> }
        | undefined
      const begun = await startSession(await project())
      const fresh: Session = {
        enabled: begun.enabled,
        rows: [...startRows.splice(0), ...begun.rows],
        loop: { ...FRESH_LOOP, note, pending },
        updating: Promise.resolve(),
        prompting: Promise.resolve(),
        gauge: FRESH_GAUGE,
        looks: { ...FRESH_LOOKS, ...saved?.checkpoint },
        fill: undefined,
        busy: false,
        hold: undefined,
        letGo: undefined,
        letGoID: undefined,
        runs: 0,
        block: saved?.block && { ...saved.block, doctrine: sessionDoctrine((await project()).settings).doctrine },
      }
      sessions.set(sessionID, sessions.get(sessionID) ?? fresh)

      return sessions.get(sessionID) ?? fresh
    }

    // A subagent runs in a child session: only the main agent shifts and is told.
    async function child(sessionID: string): Promise<boolean> {
      return (await parentOf(sessionID)) !== null
    }

    // A session the mod does not serve: a subagent's, or one the settings turned the mod off for.
    async function apart(sessionID: string, project?: () => Promise<Project>): Promise<boolean> {
      return (await child(sessionID)) || !(await state(sessionID, project)).enabled
    }

    async function parentOf(sessionID: string): Promise<string | null> {
      const known = parents.get(sessionID)
      if (known !== undefined) return known
      const info = await ctx.session.get({ sessionID }).catch(() => undefined)
      const parent = info?.parentID ?? null
      parents.set(sessionID, parent)

      return parent
    }

    // The main session a subagent's session runs under, through any depth.
    async function mainOf(sessionID: string): Promise<string> {
      const parent = await parentOf(sessionID)

      return parent === null ? sessionID : mainOf(parent)
    }

    // A row for the owner: a synthetic message the owner sees by its description; the agent reads it with the next one.
    async function tell(sessionID: string, row: string, _level: Level): Promise<void> {
      // Queued: a running turn does not take it as a message to answer.
      await ctx.session.synthetic({ sessionID, text: row, description: row, resume: false, delivery: 'queue' }).catch(() => {})
    }

    function loopOf(sessionID: string): Loop {
      return {
        read: async () => (await state(sessionID)).loop,
        // One update after another: a change made while the storage still writes the one before would build on a state
        // that may yet be taken back.
        update: async change => {
          const session = await state(sessionID)
          const turn = session.updating.then(async () => {
            const before = session.loop
            const after = change(before)
            session.loop = after
            try {
              if (after.pending !== before.pending) await keep(pendingKey(sessionID), after.pending)
              if (after.note !== before.note) await keep(waitKey(sessionID), after.note)
            } catch (error) {
              // Not kept, not changed: a shift the storage did not take is not let go either.
              session.loop = before
              throw error
            }
          })
          session.updating = turn.catch(() => {})
          await turn
        },
        tell: (row, level) => void tell(sessionID, row, level),
      }
    }

    async function keep(key: string, value: unknown): Promise<void> {
      if (value === null) await ctx.storage.remove(key)
      else await ctx.storage.set(key, value as never)
    }

    // A project loaded once for the hook at hand, and only when something asks for it.
    function once(): () => Promise<Project> {
      let loading: Promise<Project> | undefined
      return () => {
        loading ??= projectAt(root)
        return loading
      }
    }

    function courierOf(sessionID: string, project: () => Promise<Project> = once()): Courier {
      return {
        loop: loopOf(sessionID),
        gauge: keeperOf(sessionID, project),
        project,
        looks: async () => (await state(sessionID)).looks,
        updateLooks: async change => {
          const session = await state(sessionID)
          const previous = session.looks
          session.looks = change(previous)
          if (session.block && checkpointChanged(previous, session.looks)) await saveContext(sessionID, session)
        },
      }
    }

    async function saveContext(sessionID: string, session: Session) {
      const value = session.block && { block: session.block, checkpoint: mapCheckpoint(session.looks) }
      const saving = session.updating.then(() => keep(`context:${sessionID}`, value ?? null))
      session.updating = saving.catch(() => undefined)
      await saving
    }

    // The gauge in the plugin's memory; the history and the base read from the session.
    function keeperOf(sessionID: string, project: () => Promise<Project> = once()): GaugeKeeper {
      return {
        read: async () => (await state(sessionID)).gauge,
        update: async change => {
          const session = await state(sessionID)
          session.gauge = change(session.gauge)
        },
        history: async () => growthIn(await ctx.session.context({ sessionID })),
        base: async () => shiftBase(await project(), sessionID),
        reading: async () => ({ tokens: (await state(sessionID)).fill, ...(await limits(sessionID)) }),
      }
    }

    // The model's window and where opencode lets the history go by itself: the window less max(15%, 16K), its default,
    // or the `buffer` given unless it leaves nothing. Kept per model: a session that changes its model is read anew.
    async function limits(sessionID: string): Promise<{ window: number; threshold: number | undefined }> {
      const info = await ctx.session.get({ sessionID }).catch(() => undefined)
      // A session that names no model runs on the configured default.
      const fallback = info?.model === undefined ? (await ctx.model.default().catch(() => undefined))?.data : undefined
      const ref = info?.model ?? (fallback == null ? undefined : { id: fallback.id, providerID: fallback.providerID })
      if (ref === undefined) return { window: 0, threshold: undefined }
      const key = `${ref.providerID}/${ref.id}`
      const known = windows.get(key)
      if (known !== undefined) return known
      const models = (await ctx.model.list().catch(() => undefined))?.data ?? []
      const model = models.find(each => each.id === ref.id && each.providerID === ref.providerID)
      const window = model?.limit.input || model?.limit.context || 0
      if (window === 0) return { window: 0, threshold: undefined }
      const given = typeof ctx.options.buffer === 'number' && ctx.options.buffer < window ? ctx.options.buffer : undefined
      const buffer = given ?? Math.max(Math.floor(window * 0.15), window >= 32_000 ? 16_000 : 0)
      const found = { window, threshold: window - buffer }
      windows.set(key, found)

      return found
    }

    // opencode lets go through a compaction the runner takes once the session is idle; the Hold rides on its hook.
    function letGoOf(sessionID: string): LetGoHarness {
      return {
        fill: async () => (await state(sessionID)).fill,
        letGo: async instructions => {
          const session = await state(sessionID)
          const before = session.fill
          const ended = new Promise<{ text: string } | { error: string }>(done => {
            session.letGo = done
          })
          session.hold = instructions
          try {
            session.letGoID = (await ctx.session.compact({ sessionID, delivery: 'queue' })).id
            const end = await ended
            if ('error' in end) return { skip: end.error }
            await ctx.session.wait({ sessionID })
            // The next step measures it; until then the digest and the kept tail stand for it.
            const after = Math.round(end.text.length / CHARS_PER_TOKEN) + Math.min(before ?? 0, KEPT_TOKENS)

            return { messages: [{ role: 'digest', text: end.text }], before, after }
          } finally {
            session.hold = undefined
            session.letGo = undefined
            session.letGoID = undefined
          }
        },
        continueWith: async prompt => {
          await ctx.session.synthetic({ sessionID, text: prompt, description: CONTINUED })
        },
      }
    }

    // The doctrine and the session's files, read at the session's first request and again after each let-go.
    await ctx.session.hook('context', async event => {
      if (await apart(event.sessionID)) return
      const session = await state(event.sessionID)
      for (const row of session.rows.splice(0)) await tell(event.sessionID, row.text, row.level)
      if (session.block === undefined) {
        const project = await projectAt(root)
        if (project.settings.enabled && !(await staleLayout(project))) await refreshDocs(project, { tocs: false })
        const files = await sessionFiles(project, { refresh: false })
        session.block = { doctrine: sessionDoctrine(project.settings).doctrine, files: renderSessionFiles(files) }
        session.looks = { ...session.looks, map: await initialMap(project, files), mapNotes: [] }
        await saveContext(event.sessionID, session)
      }
      event.system.push({ type: 'text', text: session.block.doctrine })
      if (session.block.files !== null) event.system.push({ type: 'text', text: session.block.files })
    })

    // A compaction the agent asked for holds what its letter says; any other gets the summarizer's instructions.
    await ctx.session.hook('compaction', async event => {
      if (await apart(event.sessionID)) return
      const session = sessions.get(event.sessionID)
      // One opencode makes by itself while a shift is pending holds that shift's Hold too.
      const pending = session?.loop.pending ?? null
      const hold = session?.hold ?? (pending === null ? undefined : compactInstructions(pending))
      const text = hold ?? unassistedInstructions((await projectAt(root)).settings.files)
      event.system.push({ type: 'text', text })
    })

    // The owner's message: what changed between turns, a hint, and after a wait the letter go with it.
    // The notes go in the owner's message itself: opencode's inbox takes a message of its own separately, before or after
    // the owner's, whether it steers or waits in the queue.
    // While a shift is under way the owner's message waits here, before it enters the session: entered, it would run
    // before the shift's message, which then takes it as a note and goes first.
    await ctx.session.hook('prompt', async event => {
      const project = once()
      if (await apart(event.sessionID, project)) return
      const { sessionID } = event
      const session = await state(sessionID)
      const turn = session.prompting.then(async () => {
        const loop = loopOf(sessionID)
        const { pending, letting } = await loop.read()
        let held = false
        if (pending !== null || letting != null) {
          // Idle with a shift no let-go has claimed: its run's end was missed, and the message must not wait for it.
          if (pending !== null && letting == null && !session.busy) void afterTurn(await project(), loop, letGoOf(sessionID), false)
          held = await awaitShift(loop, ms => new Promise(done => setTimeout(done, ms)), HOLD_LIMIT)
        }
        const courier = courierOf(sessionID, project)
        await countGrowth(courier.gauge, SOURCES.owner, event.prompt.text.length)
        const told = await atPrompt(courier, { runStarts: !session.busy, owner: true })
        if (told.notes.length === 0) return
        const text = told.notes.join('\n\n')
        // After a shift the owner's words follow its message, marked as held for it, as in the other harnesses.
        event.prompt.text = held ? `${text}\n\n${HELD_NOTE([event.prompt.text])}` : `${event.prompt.text}\n\n${text}`
        await countGrowth(courier.gauge, SOURCES.attachments, text.length)
        await told.delivered()
      })
      session.prompting = turn.catch(() => undefined)
      await turn
    })

    // Every note to the agent mid-run goes with a tool's result: what changed in the records around a tool of the agent,
    // the docs after a write, a hint. A subagent's write gets only the docs.
    await ctx.tool.hook('execute.before', async event => {
      if (await apart(event.sessionID)) return
      outside.set(event.id, await beforeTool(courierOf(event.sessionID)))
    })

    await ctx.tool.hook('execute.after', async event => {
      const { sessionID } = event
      const done = event.status === 'completed' ? event.result : null
      const path = done !== null && WRITING.has(event.tool) ? (event.input as { path?: unknown }).path : undefined
      const written = typeof path === 'string' ? resolve(root, path) : undefined
      if (await child(sessionID)) {
        if (written !== undefined && (await state(await mainOf(sessionID))).enabled)
          await afterWrite(courierOf(await mainOf(sessionID)), written)
        return
      }
      if (!(await state(sessionID)).enabled) return
      const courier = courierOf(sessionID)
      if (done !== null) await countGrowth(courier.gauge, event.tool, contentChars(done.content))
      const matched = outside.has(event.id)
      const before = outside.get(event.id) ?? []
      outside.delete(event.id)
      const end =
        done === null
          ? null
          : {
              own: OURS.has(event.tool),
              readOnly: READING.has(event.tool),
              written,
              shellWrite: matched && event.tool === 'shell',
              content: event.tool === 'write' ? (event.input as { content?: string }).content : undefined,
            }
      const added = await afterTool(courier, before, end)
      if (done === null || added.length === 0) return
      const blocks = added.map(text => ({ type: 'text' as const, text }))
      const content = typeof done.content === 'string' ? [{ type: 'text' as const, text: done.content }] : (done.content ?? [])
      if (event.status === 'completed') event.result = { ...done, content: [...content, ...blocks] }
    })

    await ctx.tool.transform(tools => {
      for (const tool of start.tools) {
        tools.add({
          name: tool.name,
          description: tool.description,
          input: tool.schema,
          // Called by its name, not through the code-mode tool.
          options: { codemode: false },
          execute: async (input, call) => {
            const session = await state(call.sessionID)
            if (!session.enabled) throw new Error(`${MOD} is off in this project: its settings say enabled = false.`)
            // A tool runs only in a run: one begun before the plugin reloaded has no start the plugin heard.
            session.busy = true
            const run = session.runs
            const done = await tool.run(input as Record<string, unknown>, {
              project: () => projectAt(root),
              sessionId: async () => call.sessionID,
              now: async () => Date.now(),
              subagent: await child(call.sessionID),
              loop: loopOf(call.sessionID),
              // The session's files as this session read them: shift_setup tells which changed since.
              loaded: async () => (await state(call.sessionID)).block?.files ?? null,
              status: () => gaugeStatus(keeperOf(call.sessionID)),
              cannotLetGo: async () => null,
            })
            if ('deny' in done) throw new Error(done.deny)
            // A shift accepted after its run ended — interrupted while it was written — is not made, never one of a later
            // turn.
            if (tool.name === TOOL && (!session.busy || session.runs !== run))
              void afterTurn(await projectAt(root), loopOf(call.sessionID), letGoOf(call.sessionID), true)

            return { content: done.result }
          },
        })
      }
    })

    await ctx.command.transform(commands => {
      // The owner's word to shift: once the run going on is over, a turn of its own.
      commands.add({
        name: SHIFT_COMMAND,
        description: SHIFT_NOW_DESCRIPTION,
        execute: async ({ sessionID, prompt }) => {
          const now = await shiftNow(loopOf(sessionID), prompt.text.trim())
          await ctx.session.synthetic({ sessionID, text: now.text, description: `/${SHIFT_COMMAND}`, delivery: 'queue' })
          await now.delivered()
        },
      })
      // The letter first; the owner's words typed with the command come after it as their own message.
      commands.add({
        name: RESUME_COMMAND,
        description: RESUME_DESCRIPTION,
        execute: async ({ sessionID, prompt }) => {
          const resumed = await resumeShift(await projectAt(root))
          const words = prompt.text.trim()
          if (resumed.prompt === undefined) return tell(sessionID, resumed.text, 'info')
          await ctx.session.synthetic({ sessionID, text: resumed.prompt, description: resumed.text, resume: words === '' })
          // The newest letter went: one waiting for the owner's message is not told again.
          await dropWaiting(loopOf(sessionID))
          if (words !== '') await ctx.session.prompt({ sessionID, text: words })
        },
      })
      // For the owner: it asks the agent nothing; the agent reads it with the next message.
      commands.add({
        name: TASKS_COMMAND,
        description: TASKS_DESCRIPTION,
        execute: async ({ sessionID }) => tell(sessionID, await tasksView(await projectAt(root)), 'info'),
      })
    })

    // The runs and the let-gos, by the server's events; a let-go is awaited outside the loop that reads its end.
    async function onEvent(event: { type: string; data?: unknown }): Promise<void> {
      const data = (event.data ?? {}) as Ended & { tokens?: Tokens; reason?: string; inboxID?: string }
      if (typeof data.sessionID !== 'string' || (await apart(data.sessionID))) return
      const session = await state(data.sessionID)
      switch (event.type) {
        case 'session.execution.started':
          session.busy = true
          session.runs += 1
          return
        case 'session.step.ended': {
          const tokens = data.tokens as Tokens | undefined
          if (tokens === undefined) return
          session.fill = (tokens.input ?? 0) + (tokens.cache?.read ?? 0) + (tokens.cache?.write ?? 0)
          const said = ((tokens.output ?? 0) + (tokens.reasoning ?? 0)) * CHARS_PER_TOKEN
          await countGrowth(keeperOf(data.sessionID), SOURCES.responses, said)
          return
        }
        // Only a let-go asked for answers the shift's: one opencode makes by itself is `auto`. While a shift is pending
        // that one carries the shift's Hold, and the shift still lets go of what came after it.
        case 'session.compaction.ended':
          session.gauge = letGoGauge(data.reason === 'auto')
          session.fill = undefined
          session.block = undefined
          session.looks = { ...session.looks, map: undefined, mapNotes: [] }
          await saveContext(data.sessionID, session)
          if (data.reason !== 'auto') session.letGo?.({ text: data.text ?? '' })
          return
        case 'session.revert.committed':
          session.block = undefined
          session.looks = FRESH_LOOKS
          await saveContext(data.sessionID, session)
          return
        case 'session.compaction.failed':
          if (data.reason !== 'auto') session.letGo?.({ error: `the harness did not let the history go: ${errorText(data.error)}` })
          return
        case 'session.inbox.cancelled':
          if (data.inboxID !== undefined && data.inboxID === session.letGoID) session.letGo?.({ error: 'the let-go was cancelled' })
          return
        // A run is over, whichever way it ended: a shift held in it lets go now, unless the owner interrupted it.
        case 'session.execution.succeeded':
        case 'session.execution.failed':
        case 'session.execution.interrupted': {
          session.busy = false
          const project = once()
          await runEnded(courierOf(data.sessionID, project))
          if (session.loop.pending === null) return
          const aborted = event.type === 'session.execution.interrupted'
          void afterTurn(await project(), loopOf(data.sessionID), letGoOf(data.sessionID), aborted)
          return
        }
      }
    }

    void (async () => {
      for await (const event of ctx.event.subscribe()) {
        if (stopped) return
        await onEvent(event as { type: string; data?: unknown }).catch(() => {})
      }
    })()

    return () => {
      stopped = true
    }
  },
}

export default plugin

type Tokens = { input?: number; output?: number; reasoning?: number; cache?: { read?: number; write?: number } }

// The waiting letter of a session, in the plugin's storage.
function waitKey(sessionID: string): string {
  return `wait:${sessionID}`
}

// The shift a session accepted and has not let go yet: a reload of the plugin must not drop it.
function pendingKey(sessionID: string): string {
  return `pending:${sessionID}`
}

function errorText(error: unknown): string {
  if (typeof error === 'string') return error
  if (typeof error === 'object' && error !== null && 'message' in error) return String(error.message)

  return JSON.stringify(error)
}

// The growth of the history since the last let-go, counted the way rows are counted as they come.
function growthIn(messages: readonly unknown[]): Record<string, number> {
  let gauge = FRESH_GAUGE
  for (const message of messages as { type: string; status?: string; text?: string; content?: unknown }[]) {
    // A let-go that failed or still runs left the history before it whole.
    if (message.type === 'compaction') gauge = message.status === undefined || message.status === 'completed' ? FRESH_GAUGE : gauge
    else if (message.type === 'user') gauge = addGrowth(gauge, SOURCES.owner, message.text?.length ?? 0)
    else if (message.type === 'synthetic') gauge = addGrowth(gauge, SOURCES.attachments, message.text?.length ?? 0)
    else if (message.type === 'assistant' && Array.isArray(message.content)) {
      for (const block of message.content as { type: string; name?: string; state?: { content?: unknown } }[]) {
        if (block.type === 'tool') gauge = addGrowth(gauge, block.name ?? SOURCES.tools, contentChars(block.state?.content))
        else gauge = addGrowth(gauge, SOURCES.responses, contentChars(block))
      }
    }
  }

  return gauge.growth
}
